    __stickytape_write_module('common_sections/hostname.py', b'"""Hostname and self-resolution. Nothing changes unless a hostname is known: SYSTEM_HOSTNAME or SYSTEM_FQDN, or\nSYSTEM_DOMAIN alone, which takes the current short hostname (see base_config.infer_hostname)."""\n\nfrom actions import Cmd, EnsureLine, out\nfrom config import Config\n\n\ndef actions(c: Config):\n    if not c.static_hostname:\n        return []\n    return [\n        Cmd(\n            name=f"set hostname {c.static_hostname}",\n            argv=["hostnamectl", "set-hostname", c.static_hostname],\n            done=lambda: out("hostnamectl", "--static") == c.static_hostname,\n        ),\n        # Self-resolution without DNS: one marked line, rewritten on every run\n        EnsureLine(\n            path=c.hosts_file,\n            line=c.hosts_line,\n            marker=c.hosts_marker,\n        ),\n    ]\n')
    __stickytape_write_module('actions.py', b'"""Actions for debian-setup: the shared ones plus the package installer for this distro."""\n\nfrom __future__ import annotations\n\nfrom typing import Sequence\n\nfrom action import Action\nfrom base_actions import *  # noqa: F401,F403\nfrom base_actions import ok, out, sh\n\n\nclass AptInstall(Action):\n    def __init__(self, packages: Sequence[str]):\n        super().__init__(f"apt install {\' \'.join(packages)}")\n        self.packages = list(packages)\n\n    @staticmethod\n    def _installed(package: str) -> bool:\n        return out("dpkg-query", "-W", "-f=${db:Status-Status}", package) == "installed"\n\n    def precheck(self) -> bool:\n        missing = [p for p in self.packages if not self._installed(p)]\n        self.precheck_detail = f"not installed: {\' \'.join(missing)}" if missing else ""\n        return not missing\n\n    def run(self) -> None:\n        sh("env", "DEBIAN_FRONTEND=noninteractive", "apt-get", "install", "-y", *self.packages)\n\n    def postcheck(self) -> bool:\n        held = self.precheck()\n        self.postcheck_detail = f"still {self.precheck_detail} after apt-get install" if not held else ""\n        return held\n')
